diff --git a/applets/showdesktop/showdesktop.cpp b/applets/showdesktop/showdesktop.cpp
index 2539659ead..e791d6cff7 100644
--- a/applets/showdesktop/showdesktop.cpp
+++ b/applets/showdesktop/showdesktop.cpp
@@ -7,6 +7,9 @@
 #include "showdesktop.h"

 #include <KWindowSystem>
+#include <Plasma/Containment>
+#include <Plasma/Corona>
+#include <PlasmaQuick/AppletQuickItem>

 ShowDesktop::ShowDesktop(QObject *parent)
     : QObject(parent)
@@ -44,4 +47,31 @@ void ShowDesktop::toggleDesktop()
     setShowingDesktop(!showingDesktop());
 }

+static void closePopups(const QList<Plasma::Applet *> &applets)
+{
+    for (Plasma::Applet *applet : applets) {
+        if (auto containment = qobject_cast<Plasma::Containment *>(applet)) {
+            closePopups(containment->applets());
+        }
+        PlasmaQuick::AppletQuickItem *item = PlasmaQuick::AppletQuickItem::itemForApplet(applet);
+        if (!item || !item->hideOnWindowDeactivate() || !item->isExpanded()) {
+            continue;
+        }
+        QQuickItem *fullRepresentation = item->fullRepresentationItem();
+        if (fullRepresentation && fullRepresentation->window() != item->window()) {
+            item->setExpanded(false);
+        }
+    }
+}
+
+void AppletPopups::closeAll(Plasma::Applet *applet)
+{
+    if (!applet || !applet->containment() || !applet->containment()->corona()) {
+        return;
+    }
+
+    const auto containments = applet->containment()->corona()->containments();
+    closePopups({containments.cbegin(), containments.cend()});
+}
+
 #include "moc_showdesktop.cpp"
diff --git a/applets/showdesktop/showdesktop.h b/applets/showdesktop/showdesktop.h
index e1d678b235..e8c1038226 100644
--- a/applets/showdesktop/showdesktop.h
+++ b/applets/showdesktop/showdesktop.h
@@ -6,6 +6,7 @@

