 #include <QObject>
 #include <qqmlintegration.h>

@@ -33,3 +34,15 @@ Q_SIGNALS:
 private:
     OrgKdeKWinInterface *m_interface;
 };
+
+class AppletPopups : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+    QML_SINGLETON
+
+public:
+    using QObject::QObject;
+
+    Q_INVOKABLE void closeAll(Plasma::Applet *applet);
+};
